-- =============================================================================================
-- Hand-written below this line: committee names unique among active ones, dissolving final;
-- seats only on active committees, terms that make sense, one seat per person at a time and one
-- chair at a time, a term end set once; meetings SCHEDULED -> HELD (not before their time) or
-- CANCELLED (with a reason), agenda only while scheduled, minutes only while held and until
-- approved, approval once (by a person, recorded by the database); resolutions numbered per
-- property, only at a held meeting before its minutes are approved, never changed. See
-- docs/architecture/DATA_MODEL.md section 11 (Governance).
-- =============================================================================================

ALTER TABLE "committees" ADD CONSTRAINT "committees_text"
  CHECK ("name" = btrim("name") AND length("name") BETWEEN 1 AND 120
         AND ("purpose" IS NULL OR ("purpose" = btrim("purpose") AND length("purpose") BETWEEN 1 AND 2000))
         AND ("status" = 'DISSOLVED') = ("dissolved_at" IS NOT NULL));
CREATE UNIQUE INDEX "committees_active_name" ON "committees" ("property_id", lower("name")) WHERE "status" = 'ACTIVE';

CREATE FUNCTION app_committee_guard() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW."status" <> 'ACTIVE' THEN
      RAISE EXCEPTION 'committees start active' USING ERRCODE = 'check_violation';
    END IF;
    NEW."dissolved_at" := NULL;
    NEW."created_at" := now();
    RETURN NEW;
  END IF;
  IF OLD."status" = 'DISSOLVED' THEN
    RAISE EXCEPTION 'committee % is dissolved and no longer changes', OLD."id" USING ERRCODE = 'check_violation';
  END IF;
  IF (NEW."organisation_id", NEW."property_id", NEW."created_at") IS DISTINCT FROM (OLD."organisation_id", OLD."property_id", OLD."created_at") THEN
    RAISE EXCEPTION 'a committee stays where it is' USING ERRCODE = 'check_violation';
  END IF;
  NEW."dissolved_at" := CASE WHEN NEW."status" = 'DISSOLVED' THEN now() END;
  RETURN NEW;
END
$$;

CREATE TRIGGER "committees_guard"
  BEFORE INSERT OR UPDATE ON "committees"
  FOR EACH ROW EXECUTE FUNCTION app_committee_guard();

ALTER TABLE "committee_members" ADD CONSTRAINT "committee_members_term"
  CHECK ("term_end" IS NULL OR "term_end" >= "term_start");
ALTER TABLE "committee_members" ADD CONSTRAINT "committee_members_one_seat"
  EXCLUDE USING gist (
    "committee_id" WITH =,
    "user_id" WITH =,
    daterange("term_start", "term_end", '[]') WITH &&
  );
ALTER TABLE "committee_members" ADD CONSTRAINT "committee_members_one_chair"
  EXCLUDE USING gist (
    "committee_id" WITH =,
    daterange("term_start", "term_end", '[]') WITH &&
  ) WHERE ("position" = 'CHAIR');

CREATE FUNCTION app_committee_member_guard() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NOT EXISTS (SELECT 1 FROM "committees" WHERE "id" = NEW."committee_id" AND "status" = 'ACTIVE') THEN
      RAISE EXCEPTION 'the committee is dissolved' USING ERRCODE = 'check_violation';
    END IF;
    NEW."created_at" := now();
    RETURN NEW;
  END IF;
  IF OLD."term_end" IS NOT NULL
     OR (NEW."organisation_id", NEW."property_id", NEW."committee_id", NEW."user_id", NEW."position", NEW."term_start", NEW."created_at")
        IS DISTINCT FROM (OLD."organisation_id", OLD."property_id", OLD."committee_id", OLD."user_id", OLD."position", OLD."term_start", OLD."created_at") THEN
    RAISE EXCEPTION 'a seat changes only by setting the end of its term, once' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END
$$;

CREATE TRIGGER "committee_members_guard"
  BEFORE INSERT OR UPDATE ON "committee_members"
  FOR EACH ROW EXECUTE FUNCTION app_committee_member_guard();

ALTER TABLE "meetings" ADD CONSTRAINT "meetings_text"
  CHECK ("title" = btrim("title") AND length("title") BETWEEN 1 AND 160
         AND ("location" IS NULL OR ("location" = btrim("location") AND length("location") BETWEEN 1 AND 200))
         AND ("minutes" IS NULL OR ("minutes" = btrim("minutes") AND length("minutes") BETWEEN 1 AND 50000))
         AND ("status" = 'CANCELLED') = ("cancel_reason" IS NOT NULL)
         AND ("cancel_reason" IS NULL OR ("cancel_reason" = btrim("cancel_reason") AND length("cancel_reason") BETWEEN 1 AND 500))
         AND ("status" = 'HELD') = ("held_at" IS NOT NULL)
         AND ("minutes_approved_at" IS NULL) = ("minutes_approved_by_user_id" IS NULL)
         AND ("minutes_approved_at" IS NULL OR "minutes" IS NOT NULL)
         AND ("minutes" IS NULL OR "status" = 'HELD'));

CREATE FUNCTION app_meeting_guard() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NOT EXISTS (SELECT 1 FROM "committees" WHERE "id" = NEW."committee_id" AND "status" = 'ACTIVE') THEN
      RAISE EXCEPTION 'the committee is dissolved' USING ERRCODE = 'check_violation';
    END IF;
    IF NEW."status" <> 'SCHEDULED' OR NEW."minutes" IS NOT NULL OR NEW."minutes_approved_at" IS NOT NULL THEN
      RAISE EXCEPTION 'meetings start scheduled, without minutes' USING ERRCODE = 'check_violation';
    END IF;
    NEW."held_at" := NULL;
    NEW."created_at" := now();
    RETURN NEW;
  END IF;
  IF OLD."status" = 'CANCELLED' OR OLD."minutes_approved_at" IS NOT NULL THEN
    RAISE EXCEPTION 'meeting % is final', OLD."id" USING ERRCODE = 'check_violation';
  END IF;
  IF (NEW."organisation_id", NEW."property_id", NEW."committee_id", NEW."created_at")
     IS DISTINCT FROM (OLD."organisation_id", OLD."property_id", OLD."committee_id", OLD."created_at") THEN
    RAISE EXCEPTION 'a meeting stays with its committee' USING ERRCODE = 'check_violation';
  END IF;
  IF OLD."status" = 'HELD' AND (NEW."status", NEW."title", NEW."scheduled_at", NEW."location", NEW."held_at")
     IS DISTINCT FROM (OLD."status", OLD."title", OLD."scheduled_at", OLD."location", OLD."held_at") THEN
    RAISE EXCEPTION 'a held meeting changes only by its minutes' USING ERRCODE = 'check_violation';
  END IF;
  IF OLD."status" = 'SCHEDULED' AND NEW."status" = 'HELD' THEN
    IF OLD."scheduled_at" > now() + interval '1 hour' THEN
      RAISE EXCEPTION 'a meeting cannot be held before its time' USING ERRCODE = 'check_violation';
    END IF;
    NEW."held_at" := now();
  END IF;
  IF NEW."minutes_approved_at" IS NOT NULL THEN
    IF app_current_user_id() IS NULL THEN
      RAISE EXCEPTION 'minutes are approved by a person' USING ERRCODE = 'check_violation';
    END IF;
    NEW."minutes" := OLD."minutes";
    NEW."minutes_approved_at" := now();
    NEW."minutes_approved_by_user_id" := app_current_user_id();
  END IF;
  RETURN NEW;
END
$$;

CREATE TRIGGER "meetings_guard"
  BEFORE INSERT OR UPDATE ON "meetings"
  FOR EACH ROW EXECUTE FUNCTION app_meeting_guard();

ALTER TABLE "meeting_agenda_items" ADD CONSTRAINT "meeting_agenda_items_text"
  CHECK ("title" = btrim("title") AND length("title") BETWEEN 1 AND 200
         AND ("details" IS NULL OR ("details" = btrim("details") AND length("details") BETWEEN 1 AND 2000))
         AND "position" BETWEEN 1 AND 100);

CREATE FUNCTION app_agenda_item_guard() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM "meetings" WHERE "id" = NEW."meeting_id" AND "status" = 'SCHEDULED') THEN
    RAISE EXCEPTION 'the agenda is fixed once the meeting is held or cancelled' USING ERRCODE = 'check_violation';
  END IF;
  IF TG_OP = 'UPDATE' AND (NEW."meeting_id", NEW."organisation_id", NEW."property_id") IS DISTINCT FROM (OLD."meeting_id", OLD."organisation_id", OLD."property_id") THEN
    RAISE EXCEPTION 'an agenda item stays with its meeting' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END
$$;

CREATE TRIGGER "meeting_agenda_items_guard"
  BEFORE INSERT OR UPDATE ON "meeting_agenda_items"
  FOR EACH ROW EXECUTE FUNCTION app_agenda_item_guard();

ALTER TABLE "resolutions" ADD CONSTRAINT "resolutions_text"
  CHECK ("title" = btrim("title") AND length("title") BETWEEN 1 AND 200
         AND "text" = btrim("text") AND length("text") BETWEEN 1 AND 10000
         AND "resolution_number" IS NOT NULL AND "resolution_number" >= 1
         AND coalesce("votes_for", 0) >= 0 AND coalesce("votes_against", 0) >= 0 AND coalesce("abstentions", 0) >= 0
         AND coalesce("votes_for", 0) + coalesce("votes_against", 0) + coalesce("abstentions", 0) <= 100000);

CREATE FUNCTION app_resolution_guard() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
BEGIN
  IF TG_OP <> 'INSERT' THEN
    RAISE EXCEPTION 'resolutions are a permanent record' USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM "meetings" WHERE "id" = NEW."meeting_id" AND "status" = 'HELD' AND "minutes_approved_at" IS NULL) THEN
    RAISE EXCEPTION 'resolutions are recorded at a held meeting, before its minutes are approved' USING ERRCODE = 'check_violation';
  END IF;
  NEW."created_at" := now();
  PERFORM pg_advisory_xact_lock(hashtextextended('veyra.resolutions:' || NEW."property_id"::text, 0));
  SELECT coalesce(max("resolution_number"), 0) + 1 INTO NEW."resolution_number"
    FROM "resolutions" WHERE "property_id" = NEW."property_id";
  RETURN NEW;
END
$$;

CREATE TRIGGER "resolutions_guard"
  BEFORE INSERT OR UPDATE OR DELETE ON "resolutions"
  FOR EACH ROW EXECUTE FUNCTION app_resolution_guard();
CREATE TRIGGER "resolutions_no_truncate"
  BEFORE TRUNCATE ON "resolutions"
  FOR EACH STATEMENT EXECUTE FUNCTION app_resolution_guard();

DO $$
DECLARE
  t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['committees', 'committee_members', 'meetings', 'meeting_agenda_items', 'resolutions'] LOOP
    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY', t);
    EXECUTE format('CREATE POLICY %I ON %I FOR SELECT USING (organisation_id = app_current_organisation_id())', t || '_select', t);
    EXECUTE format('CREATE POLICY %I ON %I FOR INSERT WITH CHECK (organisation_id = app_current_organisation_id())', t || '_insert', t);
  END LOOP;
  FOREACH t IN ARRAY ARRAY['committees', 'committee_members', 'meetings', 'meeting_agenda_items'] LOOP
    EXECUTE format('CREATE POLICY %I ON %I FOR UPDATE USING (organisation_id = app_current_organisation_id()) WITH CHECK (organisation_id = app_current_organisation_id())', t || '_update', t);
  END LOOP;
END
$$;

REVOKE ALL ON "committees", "committee_members", "meetings", "meeting_agenda_items", "resolutions" FROM PUBLIC;
GRANT SELECT, INSERT, UPDATE ON "committees", "committee_members", "meetings", "meeting_agenda_items" TO veyra_app;
GRANT SELECT, INSERT ON "resolutions" TO veyra_app;
